#include <Wire.h>
#include <esp_now.h>
#include <Adafruit_MPU6050.h>
#include <Adafruit_Sensor.h>

#define POT_PIN 34  // Потенциометр на GPIO34 (ADC1_CH6)

Adafruit_MPU6050 mpu;

// Broadcast — работает с любым сервером рядом.
// Для точной адресации замените на MAC сервера (см. Serial сервера).
uint8_t broadcastAddress[] = {0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF};

typedef struct {
  int16_t angleX;
  int16_t angleY;
  uint8_t accelRange;  // 0=±2G, 1=±4G, 2=±8G, 3=±16G
} SensorPacket;

SensorPacket packet;

void OnDataSent(const uint8_t *mac_addr, esp_now_send_status_t status) {
  // Callback отправки (можно добавить LED-индикацию)
}

void setup() {
  Serial.begin(115200);
  Wire.begin(21, 22);

  if (!mpu.begin()) {
    Serial.println("MPU6050 not found!");
    while (1) { delay(100); }
  }

  // Начальный диапазон
  mpu.setAccelerometerRange(MPU6050_RANGE_8_G);
  mpu.setFilterBandwidth(MPU6050_BAND_21_HZ);

  WiFi.mode(WIFI_STA);
  Serial.print("Client MAC: ");
  Serial.println(WiFi.macAddress());

  if (esp_now_init() != ESP_OK) {
    Serial.println("ESP-NOW init failed!");
    while (1) { delay(100); }
  }

  esp_now_register_send_cb(OnDataSent);

  esp_now_peer_info_t peerInfo = {};
  memcpy(peerInfo.peer_addr, broadcastAddress, 6);
  peerInfo.channel = 0;
  peerInfo.encrypt = false;

  if (esp_now_add_peer(&peerInfo) != ESP_OK) {
    Serial.println("Failed to add peer");
    while (1) { delay(100); }
  }

  Serial.println("Client ready.");
}

void loop() {
  // --- Регулировка чувствительности потенциометром ---
  int potValue = analogRead(POT_PIN);
  // Усреднение (опционально): potValue = (potValue + analogRead(POT_PIN)) / 2;

  uint8_t range = potValue / 1024;  // 0..3
  if (range > 3) range = 3;

  static uint8_t lastRange = 255;
  if (range != lastRange) {
    mpu.setAccelerometerRange((mpu6050_accel_range_t)range);
    lastRange = range;

    const char* names[] = {"±2G", "±4G", "±8G", "±16G"};
    Serial.print("Range: "); Serial.println(names[range]);
  }

  // --- Чтение MPU6050 ---
  sensors_event_t a, g, temp;
  mpu.getEvent(&a, &g, &temp);

  int angleX = atan2(a.acceleration.y, a.acceleration.z) * 180.0 / M_PI;
  int angleY = atan2(-a.acceleration.x,
                     sqrt(a.acceleration.y * a.acceleration.y +
                          a.acceleration.z * a.acceleration.z)) * 180.0 / M_PI;

  packet.angleX = angleX;
  packet.angleY = angleY;
  packet.accelRange = range;

  // --- Отправка на сервер ---
  esp_err_t result = esp_now_send(broadcastAddress, (uint8_t *)&packet, sizeof(packet));
  if (result != ESP_OK) {
    Serial.println("Send error");
  }

  delay(200);
}
